Os quatro juntos, com o resultado em cada linha:

```
// flat: desdobra listas dentro de listas.
const tabuleiro = [[1, 2], [3], [4, 5]];
tabuleiro.flat(); // [1, 2, 3, 4, 5]

// flatMap: cada item vira uma lista e as listas são abertas.
const grupos = [['Ana'], ['Beto', 'Caio']];
grupos.flatMap((g) => g); // ['Ana', 'Beto', 'Caio']

// Array.from: cria a sequência de 1 até 3.
Array.from({ length: 3 }, (_, posicao) => posicao + 1); // [1, 2, 3]

// fill: pinta todos os itens com o mesmo valor.
const vagas = new Array(3).fill('livre'); // ['livre', 'livre', 'livre']
```

**Atenção que vale ouro:** `flat()` só abre UM nível por padrão — `[[1, [2]]].flat()` devolve `[1, [2]]`, com a caixa interna ainda fechada. Para abrir tudo: `flat(Infinity)`. E `fill` mexe na lista que recebe — na dúvida, copie antes.

code.code:
const tabuleiro = [[1, 2], [3], [4, 5]];
console.log(tabuleiro.flat()); // [1, 2, 3, 4, 5]

const grupos = [['Ana'], ['Beto', 'Caio']];
console.log(grupos.flatMap((g) => g)); // ['Ana', 'Beto', 'Caio']

console.log(Array.from({ length: 3 }, (_, i) => i + 1)); // [1, 2, 3]

const quartos = new Array(3).fill('vago');
console.log(quartos); // ['vago', 'vago', 'vago']

// Passo 1: conferimos que veio uma lista de verdade.
function listarConvidados(mesas) {
  if (!Array.isArray(mesas)) {
    throw new Error('mesas precisa ser uma lista');
  }

  // Passo 2: flat abre as mesas e junta todos os convidados.
  return mesas.flat();
}

console.log(listarConvidados([['Ana', 'Beto'], ['Caio'], ['Duda', 'Eva', 'Fábio']]));
// imprime: ['Ana', 'Beto', 'Caio', 'Duda', 'Eva', 'Fábio']
